        { t: "الاقتصادية والتنمية: رئيس وواحد وعشرون", d: "وجميع أعضاء المجلسين أعضاء في مجلس الوزراء.", pg: "321–322" },
        { t: "سكرتارية ومكتب لإدارة المشروعات", d: "السكرتارية تابعة للأمانة العامة لمجلس الوزراء، والمكتب يتابع تنفيذ الجهات المعنية.", pg: "322" },
        { t: "الكفاءة والتنسيق والتحرر من البيروقراطية", d: "رفع أداء الأجهزة الحكومية، وتفادي الازدواجية وبطء العمل.", pg: "322–323" }
