    { t: "التشكيلات الإدارية للمجلس والوزارات", pg: "323–331", c: [
      { t: "جهازان إداريان للمجلس", d: "الأمانة العامة لمجلس الوزراء، وهيئة الخبراء.", pg: "323" },
      { t: "الأمانة العامة لمجلس الوزراء", pg: "324–325", c: [
        { t: "أمين عام بمرتبة وزير", d: "يحق له حضور جلسات المجلس، وله نائب بالمرتبة الممتازة.", pg: "324" },
        { t: "مهام الأمين العام: خمس من أهمها", d: "الهيكل الإداري، وجداول الأعمال والمحاضر، والوثائق والمعلومات، وميزانية الأمانة، وما يكلفه به المجلس.", pg: "324" },
        { t: "اختصاصات الأمانة: منها خمسة", d: "الجلسات الأسبوعية، وتوصيات اللجنة العامة، وتجهيز القرارات، وسكرتارية اللجنة العامة، وهمزة الوصل.", pg: "325" }
      ] },
      { t: "هيئة الخبراء", pg: "325–327", c: [
        { t: "جهاز استشاري لمجلس الوزراء", d: "الرئيس ونائبه ومساعده والمستشارون، ولجان متخصصة تشكل عند الحاجة؛ واسمها الأول شعبة الخبراء.", pg: "325–326" },
        { t: "ستة اختصاصات", d: "كل ما يتعلق بصياغة وتعديل الأنظمة ومراجعة الاتفاقيات الدولية التي تنتسب إليها المملكة.", pg: "326–327" }
      ] },
      { t: "الديوان الملكي محل ديوان الرئاسة", d: "حلقة الاتصال الرسمية الوحيدة بين الملك وباقي أجهزة الدولة والمواطنين.", pg: "327" },
      { t: "الوزارة عموماً أكبر أقسام الجهاز التنفيذي", d: "يرأسها مسؤول بمرتبة وزير، مسؤول أمام رئيس مجلس الوزراء.", pg: "327" },
      { t: "عدد الوزارات بلا قيد نظامي", d: "انتفاء القيد أتاح مرونة نظامية؛ وعدد بعض الوزارات ومسماها مرهون بمتطلبات كل مرحلة.", pg: "329–330" },
      { t: "اختصاصات الوزارة الخمسة", d: "سياستها العامة، والتمثيل الدولي، ومسودة الأنظمة، والتوقيع بالأحرف الأولى، واللوائح التنفيذية والتفسيرية.", pg: "330" },
      { t: "مسؤوليات المجلس ومساندة الشورى", d: "تصريف شؤون الدولة بجانب الملك، وخطط التنمية الاقتصادية، والشورى شريك في السلطة التنظيمية.", pg: "330–331" }
    ] }
